insert into public.content_items (type, category, recommended_time, translations, is_active) values
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Yaptığım işlerin kötülüğünden de henüz yapmadığım işlerin kötülüğünden de sana sığınırım!", "source": "Müslim, Zikir, 65"}, "en": {"content": "O Allah! I seek refuge in You from the evil of what I have done and from the evil of what I have not yet done.", "source": "Sahih Muslim, Book of Dhikr, 65"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbim! Girilecek yere doğrulukla girmemi, çıkılacak yerden de doğrulukla çıkmamı sağla, bana tarafından yardımcı bir güç ver.", "source": "İsrâ, 17/80"}, "en": {"content": "My Lord, cause me to enter a sound entrance and to exit a sound exit and grant me from Yourself a supporting authority.", "source": "Surah Al-Isra, 17:80"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım! Sana teslim olan bir kalp, doğru sözlü bir dil ve dosdoğru bir ahlak istiyorum.", "source": "Hâkim, Deavât, No: 1872"}, "en": {"content": "O Allah! I ask You for a heart submissive to You, a truthful tongue, and upright character.", "source": "Al-Hakim, Al-Da''awat, No: 1872"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ın gazabından, kullarının şerrinden, şeytanların vesveselerinden ve (onların) bana uğramalarından Allah’ın tam kelimelerine sığınırım.", "source": "Ebu Davud, Tıb, 19"}, "en": {"content": "I seek refuge in the perfect words of Allah from His anger, the evil of His servants, the whispers of devils, and from their presence.", "source": "Sunan Abi Dawud, Book of Medicine, 19"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım, nefsime takvasını ver, onu temizle, onu temizleyenlerin en hayırlısı sensin. Onun velisi (sahibi) ve mevlası (efendisi) sensin.", "source": "Müslim, Zikir, Dua, Tevbe ve İstiğfar, 73"}, "en": {"content": "O Allah, grant my soul its piety and purify it, for You are the best of those who purify it. You are its Guardian and Master.", "source": "Sahih Muslim, Book of Repentance, 73"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Müslümanlar olarak canımızı al, bizi Müslümanlar olarak dirilt, rezil olmadan ve fitneye uğramadan salih kullarının arasına dâhil eyle.", "source": "Hâkim, Deavât, No: 1868"}, "en": {"content": "O Allah! Cause us to die as Muslims, raise us as Muslims, and join us with the righteous, without being disgraced or put to trial.", "source": "Al-Hakim, Al-Da''awat, No: 1868"}}',true),
('prayer','prayer','any','{"tr": {"content": "(Allah’ım!) Zenginlikle imtihan edilmenin kötülüğünden sana sığınırım. Fakirlikle imtihan edilmenin kötülüğünden de sana sığınırım.", "source": "Buhârî, Deavât, 39"}, "en": {"content": "O Allah! I seek refuge in You from the trials of wealth, and I seek refuge in You from the trials of poverty.", "source": "Sahih al-Bukhari, Book of Supplications, 39"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey Rabbimiz! Sen rahmetin ve ilminle her şeyi kuşattın. Tövbe edenleri ve yolundan gidenleri bağışla, onları cehennem azabından koru!", "source": "Mü’min, 40/7"}, "en": {"content": "Our Lord, You have encompassed all things in mercy and knowledge, so forgive those who have repented and followed Your way and protect them from the punishment of Hellfire.", "source": "Surah Ghafir, 40:7"}}',true),
('prayer','prayer','morning','{"tr": {"content": "Allah’ım! Senin iznin ve yardımınla sabahledik ve akşamladık. Yine senin izin ve yardımınla yaşar ve ölürüz. Sonunda dönüş yalnız sanadır.", "source": "Ebu Davud, Edeb, 110"}, "en": {"content": "O Allah! By Your leave we enter the morning and by Your leave we enter the evening, by Your leave we live and by Your leave we die, and unto You is the resurrection.", "source": "Sunan Abi Dawud, Book of Manners, 110"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Bana kendi sevgini ve senin yanında sevgisi bana fayda verecek kimsenin sevgisini ver.", "source": "Tirmizî, Deavât, 73"}, "en": {"content": "O Allah! Grant me Your love, and the love of those whose love will benefit me with You.", "source": "Jami` at-Tirmidhi, Book of Supplications, 73"}}',true),
('prayer','hope','any','{"tr": {"content": "Ey insanların Rabbi! Rahatsızlığı gider! Şifa veren sensin. Senin vereceğin şifadan başka şifa yoktur. Öyle bir şifa ver ki ardında hiç hastalık izi bırakmasın.", "source": "Müslim, Selâm, 47"}, "en": {"content": "O Lord of mankind! Remove the difficulty! Heal, for You are the Healer. There is no healing but Your healing. Grant a healing that leaves no illness behind.", "source": "Sahih Muslim, Book of Greetings, 47"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Sen affedicisin, Kerim’sin, affı seversin, beni affet.", "source": "Tirmizî, Deavât, 84"}, "en": {"content": "O Allah! You are forgiving, noble, and You love forgiveness, so forgive me.", "source": "Jami` at-Tirmidhi, Book of Supplications, 84"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Cehenneme götüren fitneden, cehennemin azabından, zenginliğin ve fakirliğin şerrinden sana sığınırım.", "source": "Ebû Dâvûd, Vitr, 32"}, "en": {"content": "O Allah! I seek refuge in You from the trials that lead to Hell, from the punishment of Hell, and from the evils of wealth and poverty.", "source": "Sunan Abi Dawud, Book of Witras, 32"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Ayakta iken beni İslam ile koru, otururken beni İslam ile koru, uyurken beni İslam ile koru, hakkımda hiçbir düşman ve hasetçinin isteğini yerine getirme.", "source": "İbn Hibban, Ed’ıye, No: 934"}, "en": {"content": "O Allah! Protect me with Islam when standing, protect me with Islam when sitting, protect me with Islam when sleeping, and do not let any enemy or envier rejoice over me.", "source": "Sahih Ibn Hibban, Al-Ad`iyah, No: 934"}}',true),
('prayer','hope','any','{"tr": {"content": "Rabbimiz! Bize katından rahmet gönder ve bize içinde bulunduğumuz durumdan bir çıkış yolu göster!", "source": "Kehf, 18/10"}, "en": {"content": "Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance.", "source": "Surah Al-Kahf, 18:10"}}',true),
('prayer','worship','any','{"tr": {"content": "Allah’ım! Ey Rabbimiz ve ey her şeyin Rabbi! Beni ve ailemi dünya ve ahirette her an sana ihlasla bağlı kıl. Ey yücelik ve ikram sahibi!...", "source": "Ebû Dâvûd, Vitr, 25"}, "en": {"content": "O Allah! Owner of sovereignty, make me and my family sincere to You in this world and the next. O Owner of Majesty and Honor!", "source": "Sunan Abi Dawud, Book of Witras, 25"}}',true),
('prayer','dhikr','any','{"tr": {"content": "Ey Rabbim! Gerek bana gerekse anne-babama verdiğin nimete şükretmeye ve hoşnut olacağın iyi işler yapmaya beni muvaffak kıl. Rahmetinle beni iyi kullarının arasına kat!", "source": "Neml, 27/19"}, "en": {"content": "My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to do righteousness of which You approve. And admit me by Your mercy into the ranks of Your righteous servants.", "source": "Surah Al-Naml, 27:19"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Günahlarımızdan ve işimizdeki aşırılıklardan ötürü bizi bağışla, sebatımızı arttır, kâfir topluluğa karşı bize yardım et!", "source": "Âl-i İmrân, 3/147"}, "en": {"content": "Our Lord! Forgive us our sins and our excesses in our affairs, make our steps firm, and give us victory over the disbelieving people.", "source": "Surah Ali ''Imran, 3:147"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Gidip ebedî yaşayacağım ahiret hayatımı benim için hayırlı eyle. Hayatımda her türlü hayrı ziyadesiyle ihsan eyle. Ölümümü de her türlü şerlerden muhafaza eyle.", "source": "Müslim, Duâ, 71"}, "en": {"content": "O Allah! Make my hereafter good, which is my eternal home. Grant me abundance in all good things in my life, and make my death a relief from every evil.", "source": "Sahih Muslim, Book of Supplication, 71"}}',true),
('prayer','worship','any','{"tr": {"content": "Rabbim! Tövbemi kabul et, günahımı temizle, duamı kabul buyur, delilimi sabit kıl, dilimi doğru yap, kalbime hidayet ver, göğsümün kin ve hasedini çıkar.", "source": "Tirmizî, Deavât, 114"}, "en": {"content": "My Lord! Accept my repentance, wash away my sin, answer my prayer, make my proof firm, guide my heart, make my tongue truthful, and remove malice from my chest.", "source": "Jami` at-Tirmidhi, Book of Supplications, 114"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Kıyamet gününde cennet, korku gününde güven istiyorum. Allah’ım! Verdiğin ve vermediğin şeylerin şerrinden sana sığınıyorum.", "source": "Hâkim, Deavât, No: 1868"}, "en": {"content": "O Allah! I ask You for Paradise on the Day of Judgment, and safety on the Day of Fear. O Allah! I seek refuge in You from the evil of what You have given us and what You have withheld.", "source": "Al-Hakim, Al-Da''awat, No: 1868"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Kulağımın kötülüğünden, gözümün kötülüğünden, dilimin kötülüğünden, kalbimin kötülüğünden, tenimin kötülüğünden sana sığınırım.", "source": "Nesâî, İstiâze, 4"}, "en": {"content": "O Allah! I seek refuge in You from the evil of my hearing, from the evil of my seeing, from the evil of my tongue, from the evil of my heart, and from the evil of my desire.", "source": "Sunan an-Nasa''i, Book of Isti''adha, 4"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Sen yardım istenilensin, dualar ancak sana ulaşır, duaları sen kabul edersin, güç ve kuvvet ancak Allah ile birlikte vardır.", "source": "Tirmizî, Deavât, 94"}, "en": {"content": "O Allah! You are the One whose help is sought, prayers reach You, You accept prayers, and there is no power or strength except with Allah.", "source": "Jami` at-Tirmidhi, Book of Supplications, 94"}}',true),
('prayer','purpose','any','{"tr": {"content": "(Allah’ım!) Beni güzel ahlaka eriştir. Senden başka güzel ahlaka eriştirecek yoktur. Kötü ahlakı benden uzaklaştır. Senden başka kötü ahlakı benden uzaklaştıracak yoktur!", "source": "Müslim, Müsâfirîn, 201"}, "en": {"content": "O Allah! Guide me to the best character. None can guide to it except You. Divert from me bad character. None can divert it from me except You.", "source": "Sahih Muslim, Book of Travellers, 201"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Mal, aile, child olarak insanlara verdiklerinin hayırlısını dilerim, sapıtan ve saptıranları değil.", "source": "Tirmizî, Deavât, 124"}, "en": {"content": "O Allah! I ask You for the best of what You give to people of wealth, family, and children, not those who are astray or lead others astray.", "source": "Jami` at-Tirmidhi, Book of Supplications, 124"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Bizi sabırla donat, bize sebat ver ve inkârcı topluluğa karşı bize yardım et.", "source": "Bakara, 2/250"}, "en": {"content": "Our Lord! Pour upon us patience, make our steps firm, and help us against the disbelieving people.", "source": "Surah Al-Baqarah, 2:250"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Sevgini, seni seven kimsenin sevgisini ve sevgine ulaştıracak ameli istiyorum. Allah’ım! Sevgini, bana canımdan, ailemden ve soğuk sudan daha sevimli eyle.", "source": "Tirmizî, Deavât, 74"}, "en": {"content": "O Allah! I ask You for Your love, the love of those who love You, and the deeds that lead to Your love. O Allah! Make Your love dearer to me than my own self, my family, and cold water.", "source": "Jami` at-Tirmidhi, Book of Supplications, 74"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Her işimin koruyucusu olan dinim ile beni ıslah eyle, kurtuluşa erdir. İçinde yaşadığım, geçimimi sağladığım dünyamı benim için ıslah eyle, hayırlı kıl.", "source": "Müslim, Duâ, 71"}, "en": {"content": "O Allah! Rectify for me my religion which is the safeguard of my affairs, rectify for me my world in which is my livelihood, and make my life a source of increase in every good.", "source": "Sahih Muslim, Book of Supplication, 71"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Dinim, dünyam, ailem ve malım hakkında af ve afiyet istiyorum.", "source": "Hâkim, Deavât, No: 1902"}, "en": {"content": "O Allah! I ask You for guidance, piety, chastity, and contentment.", "source": "Al-Hakim, Al-Da''awat, No: 1902"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım, cimrilikten sana sığınırım, korkaklıktan sana sığınırım, ömrün en rezil zamanına kalmaktan sana sığınırım.", "source": "Buhârî, Deavât, 37"}, "en": {"content": "O Allah! I seek refuge in You from miserliness, I seek refuge in You from cowardice, and I seek refuge in You from reaching the most miserable stage of life.", "source": "Sahih al-Bukhari, Book of Supplications, 37"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Beni, iyilik yaptıkları zaman sevinç duyan, kötülük yaptıkları zaman da bağışlanma dileyen kullarından eyle.", "source": "İbn Mâce, Edeb, 57"}, "en": {"content": "O Allah! Make me among those who rejoice when they do good, and seek forgiveness when they do evil.", "source": "Sunan Ibn Majah, Book of Manners, 57"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Kötü ahlaktan, nefsani arzulardan, kötü işlerden ve ayıp şeylerden beni uzaklaştır.", "source": "İbn Hibban, Ed’ıye, No: 960"}, "en": {"content": "O Allah! Keep me away from bad character, evil desires, bad deeds, and disgraceful things.", "source": "Sahih Ibn Hibban, Al-Ad`iyah, No: 960"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Fakirlikten, yoksulluktan ve zilletten sana sığınırım. Haksızlık etmekten ve haksızlığa uğramaktan da sana sığınırım.", "source": "Ebû Dâvûd, Vitr, 32"}, "en": {"content": "O Allah! I seek refuge in You from poverty, scarcity, and humiliation. And I seek refuge in You from committing injustice or being subjected to it.", "source": "Sunan Abi Dawud, Book of Witras, 32"}}',true),
('prayer','worship','any','{"tr": {"content": "Ey Rabbimiz! Üzerimize sabır yağdır ve Müslüman olarak bizim canımızı al.", "source": "A’râf, 7/126"}, "en": {"content": "Our Lord! Pour upon us patience and cause us to die as Muslims.", "source": "Surah Al-A''raf, 7:126"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey Rabbimiz! Bizi ve imanda bizden önce olan din kardeşlerimizi mağfiret eyle ve kalbimizde mü’minler için kin ve haset bırakma. Ey Rabbimiz! Sen çok şefkat ve çok merhamet sahibisin.", "source": "Haşr, 59/10"}, "en": {"content": "Our Lord! Forgive us and our brothers who preceded us in faith, and put not in our hearts any resentment toward those who have believed. Our Lord, indeed You are Kind and Merciful.", "source": "Surah Al-Hashr, 59:10"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Bizi, inkâr edenler için bir sınama konusu yapma. Bizi bağışla ey Rabbimiz! Çünkü kudret ve hikmet sahibi olan ancak sensin.", "source": "Mümtehine, 60/5"}, "en": {"content": "Our Lord! Make us not a trial for those who disbelieve and forgive us, our Lord. Indeed, You are the Exalted in Might, the Wise.", "source": "Surah Al-Mumtahinah, 60:5"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Peygamberlerin aracılığıyla bize vaad ettiklerini ver bize; kıyamet gününde bizi rezil etme. Sen asla sözünden dönmezsin.", "source": "Âl-i İmrân, 3/194"}, "en": {"content": "Our Lord! Grant us what You promised us through Your messengers and disgrace us not on the Day of Resurrection. Indeed, You never fail in Your promise.", "source": "Surah Ali ''Imran, 3:194"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Bizi doğru yola eriştirdikten sonra kalplerimizi saptırma, bize tarafından bir rahmet bağışla. Hiç kuşku yok, lütfu bol olan yalnız sensin.", "source": "Âl-i İmrân, 3/8"}, "en": {"content": "Our Lord! Let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.", "source": "Surah Ali ''Imran, 3:8"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım! Senden hidayet, takva, iffet ve gönül zenginliği istiyorum.", "source": "Müslim, Duâ, 72"}, "en": {"content": "O Allah! I ask You for guidance, piety, chastity, and contentment.", "source": "Sahih Muslim, Book of Supplication, 72"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey Rabbim! Beni ve kardeşimi bağışla, bizi rahmetine gark eyle! Sen merhametlilerin en merhametlisisin.", "source": "A’râf, 7/151"}, "en": {"content": "My Lord! Forgive me and my brother and admit us into Your mercy, for You are the most merciful of the merciful.", "source": "Surah Al-A''raf, 7:151"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım! Bana öğrettiğin şeyleri hakkımda faydalı eyle, bana fayda verecek şeyleri öğret; beni, bana fayda verecek ilim ile nasiplendir.", "source": "Hâkim, Deavât, No: 1879, I"}, "en": {"content": "O Allah! Benefit me with what You have taught me, teach me what will benefit me, and grant me knowledge that will be of benefit to me.", "source": "Al-Hakim, Al-Da''awat, No: 1879, I"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Günahlarımın küçüğünü büyüğünü, öncesini sonunu, açığını ve gizlisini, hepsini bağışla.", "source": "Müslim, Salât, 216"}, "en": {"content": "O Allah! Forgive all my sins, the small and the great, the first and the last, the open and the secret.", "source": "Sahih Muslim, Book of Salat, 216"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Hesap kurulacağı gün beni, anamı, babamı ve mü’minleri bağışla!", "source": "İbrahim, 14/41"}, "en": {"content": "Our Lord! Forgive me and my parents and the believers on the Day the account is established.", "source": "Surah Ibrahim, 14:41"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Ey Rabbimiz! Bize gökten öyle bir sofra indir ki, ilk gelenimizden son gelenimize kadar bizler için bir bayram ziyafeti ve senden bir işaret olsun. Bizi rızıklandır, sen rızık verenlerin en hayırlısısın.", "source": "Mâide, 5/114"}, "en": {"content": "O Allah, our Lord! Send down to us a table spread from heaven to be for us a festival for the first of us and the last of us and a sign from You. And provide for us, and You are the best of providers.", "source": "Surah Al-Ma''idah, 5:114"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Lütfun, rahmetin, bereketin ve rızkından bana aç, bolca ihsan eyle.", "source": "Hâkim, Deavât, No: 1868"}, "en": {"content": "O Allah! Open for me Your grace, mercy, blessings, and provisions, and grant me in abundance.", "source": "Al-Hakim, Al-Da''awat, No: 1868"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Yolculuğun yorgunluk ve sıkıntılarından, yoldan kötü bir şekilde dönmekten, iyi hâllerden kötü hâllere düşmekten, mazlumun bedduasından, mala ve aileye gelecek kötülüklerden sana sığınırım.", "source": "Müslim, Hac, 426"}, "en": {"content": "O Allah! I seek refuge in You from the hardships and difficulties of travel, from returning in a bad state, from falling from a good state to a bad state, from the supplication of the oppressed, and from evil befalling wealth and family.", "source": "Sahih Muslim, Book of Hajj, 426"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Günahlarımı kar ve dolu suyu ile yıka ve beyaz elbiseyi kirden temizler gibi kalbimi hatalardan arındır.", "source": "Buhârî, Deavât, 39"}, "en": {"content": "O Allah! Wash away my sins with snow and hail water, and purify my heart from sins as a white garment is purified from filth.", "source": "Sahih al-Bukhari, Book of Supplications, 39"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Bildiğin günahlarımı bağışlamanı istiyorum. Bildiğin her türlü hayırdan istiyorum. Bildiğin bütün şeylerden sana sığınıyorum. Süphesiz sen gaybı/gizli olan şeyleri en iyi bilensin.", "source": "Hâkim, Deavât, No: 1872"}, "en": {"content": "O Allah! I ask You for the forgiveness of my sins that You know. I ask You for every good that You know. I seek refuge in You from all evil that You know. Indeed, You are the Knower of the unseen.", "source": "Al-Hakim, Al-Da''awat, No: 1872"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Açlıktan sana sığınırım. Çünkü açlık ne kötü bir arkadaştır. Hainlikten de sana sığınırım. Çünkü hainlik ne kötü bir sırdaştır.", "source": "Ebû Dâvûd, Vitr, 32"}, "en": {"content": "O Allah! I seek refuge in You from hunger, for it is indeed an evil companion. And I seek refuge in You from treachery, for it is indeed an evil confidant.", "source": "Sunan Abi Dawud, Book of Witras, 32"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Beni bağışla, bana hidayet nasip eyle, bana rızık ver, beni afiyette daim eyle ve bana merhamet et.", "source": "Müslim, Zikir ve Duâ, 35"}, "en": {"content": "O Allah! Forgive me, guide me, provide for me, keep me in good health, and have mercy on me.", "source": "Sahih Muslim, Book of Repentance, 35"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Bize imanı sevdir, kalplerimizi imanla süsle. Bize küfrü, itaatsizliği ve isyanı sevdirme, kerih göster, bizi doğru yolu bulanlardan eyle.", "source": "Hâkim, Deavât, No: 1868"}, "en": {"content": "O Allah! Make faith beloved to us and beautify it in our hearts, and make disbelief, defiance, and disobedience hateful to us. And make us among the rightly guided.", "source": "Al-Hakim, Al-Da''awat, No: 1868"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! İndirdiğine inandık ve Peygambere tâbi olduk; artık bizi şahitlerle beraber yaz.", "source": "Âl-i İmrân, 3/53"}, "en": {"content": "Our Lord! We have believed in what You revealed and have followed the messenger, so register us among the witnesses.", "source": "Surah Ali ''Imran, 3:53"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey Rabbimiz! Bizi sana teslim olanlardan eyle, soyumuzdan da sana teslim olacak bir ümmet çıkar. Bize ibadet usullerimizi göster, tevbemizi kabul et. Şüphesiz tövbeleri kabul eden, merhameti bol olan sensin.", "source": "Bakara, 2/128"}, "en": {"content": "Our Lord! Make us submissive to You and from our descendants a nation submissive to You. And show us our rites and accept our repentance. Indeed, You are the Accepting of repentance, the Merciful.", "source": "Surah Al-Baqarah, 2:128"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Ciddi ve şaka yollu yaptıklarımı, yanlışlıkla ve bilerek işlediğim günahlarımı affeyle! Bütün bu kusurların bende bulunduğunu itiraf ederim.", "source": "Müslim, Zikir, 70"}, "en": {"content": "O Allah! Forgive my jokes and my serious deeds, my accidental and my intentional sins. I confess that all of these are in me.", "source": "Sahih Muslim, Book of Dhikr, 70"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım! Beni amellerin ve ahlakın en güzeline kavuştur. Onların en güzeline ancak sen ulaştırırsın. Beni kötü işlerden ve kötü ahlaktan muhafaza et. Bunlardan ancak sen koruyabilirsin.", "source": "Nesâî, İftitâh, 16"}, "en": {"content": "O Allah! Guide me to the best of deeds and character. None can guide to the best of them except You. Protect me from evil deeds and character. None can protect from them except You.", "source": "Sunan an-Nasa''i, Book of Iftitah, 16"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Şüphesiz ben nefsime çok zulmettim, günahları bağışlayacak olan yalnız sensin. Öyleyse katından bir af ile beni bağışla. Bana merhamet et, çünkü bağışlaması ve rahmeti çok olan sadece sensin.", "source": "Buhari, Ezan, 149"}, "en": {"content": "O Allah! Indeed I have wronged my soul greatly, and none forgives sins except You. So forgive me with forgiveness from You and have mercy on me. Indeed, You are the Forgiving, the Merciful.", "source": "Sahih al-Bukhari, Book of Adhan, 149"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey mülkün gerçek sahibi olan Allah’ım! Mülkü dilediğine verirsin, dilediğinden çekip alırsın. Dilediğini yüceltirsin, dilediğini de alçaltırsın. Her türlü iyilik senin elindedir. Hiç kuşku yok sen her şeye kâdirsin.", "source": "Âl-i İmrân, 3/36"}, "en": {"content": "O Allah, Owner of Sovereignty! You give sovereignty to whom You will and You take sovereignty away from whom You will. You honor whom You will and You humble whom You will. In Your hand is all good. Indeed, You are over all things competent.", "source": "Surah Ali ''Imran, 3:26"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Bana verdiğin rızık konusunda beni kanaat sahibi yap ve o rızkımı bereketli kıl. Zayi olan her nimetin daha hayırlısını bana ihsan eyle.", "source": "Hâkim, Deavât, No: 1878"}, "en": {"content": "O Allah! Make me content with what You have provided for me, bless it for me, and replace what is lost with something better.", "source": "Al-Hakim, Al-Da''awat, No: 1878"}}',true),
('prayer','hope','any','{"tr": {"content": "Allah’ım! Açıklarımı ört, korkularımı gider ve bana güven ver. Allah’ım! Ayıplarımı ört ve korkularımı gider.", "source": "Hâkim, Deavât, No: 1902, I"}, "en": {"content": "O Allah! Cover my faults, calm my fears, and grant me security. O Allah! Cover my weaknesses and ease my anxiety.", "source": "Al-Hakim, Al-Da''awat, No: 1902, I"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Tövbelerimizi kabul eyle, süphesiz ki sen tövbeleri çok kabul edensin, çok merhametlisin. Bizi nimetlerine şükredenler, nimetlerinle seni övenler, verdiğin nimetleri kabul edenlerden eyle ve bize nimetlerin devamını ihsan eyle.", "source": "Hâkim, Temin, No: 977"}, "en": {"content": "O Allah! Accept our repentance. Indeed, You are the Accepting of repentance, the Merciful. Make us grateful for Your blessings, praising You for them, accepting them, and complete them upon us.", "source": "Al-Hakim, Al-Da''awat, No: 977"}}',true),
('prayer','prayer','any','{"tr": {"content": "(Rabbim!) İnsanların diriltileceği gün ve Allah’a temiz bir kalple gelenler dışında malın da çocukların da fayda vermeyeceği gün beni mahcup etme!", "source": "Şu’arâ, 26/87-89"}, "en": {"content": "My Lord! Disgrace me not on the Day they are resurrected — The Day when there will not benefit wealth or children, except one who comes to Allah with a clean heart.", "source": "Surah Al-Shu''ara, 26:87-89"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Bütün işlerimdeki ölçüsüzlüğümü, cahilliğimi ve hatamı bağışla. Sen bunları benden daha iyi biliyorsun.", "source": "Buhari, Deavât, 60"}, "en": {"content": "O Allah! Forgive my ignorance, my excesses in my affairs, and my mistakes, which You know better than I.", "source": "Sahih al-Bukhari, Book of Supplications, 60"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey kalpleri evirip çeviren (Allah’ım!) Benim kalbimi dinin üzere sabit kıl.", "source": "Tirmizî, Deavât, 89"}, "en": {"content": "O Turner of the hearts! Keep my heart firm upon Your religion.", "source": "Jami` at-Tirmidhi, Book of Supplications, 89"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Sen bunu boş yere yaratmadın, seni tenzih ve takdis ederiz. Bizi cehennem azabından koru!", "source": "Âl-i İmrân, 3/191"}, "en": {"content": "Our Lord! You did not create this uselessly; exalted are You; so protect us from the punishment of the Fire.", "source": "Surah Ali ''Imran, 3:191"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Bana doğru olanı ilham et ve beni nefsimin şerrinden koru.", "source": "Tirmizî, Deavât, 70"}, "en": {"content": "O Allah! Inspire me with guidance and protect me from the evil of my own soul.", "source": "Jami` at-Tirmidhi, Book of Supplications, 70"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbim! Bana tarafından temiz bir nesil ihsan eyle! Kuşkusuz sen duayı işitmektesin.", "source": "Âl-i İmrân, 3/38"}, "en": {"content": "My Lord! Grant me from Yourself a good offspring. Indeed, You are the Hearer of supplication.", "source": "Surah Ali ''Imran, 3:38"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Ancak sana dayandık, sana yönelledik. Dönüş de ancak sanadır.", "source": "Mümtehine, 60/4"}, "en": {"content": "Our Lord! Upon You we have relied, and to You we have returned, and to You is the destination.", "source": "Surah Al-Mumtahinah, 60:4"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey Rabbimiz! Biz gerçekten iman ettik, günahlarımızı bağışla, bizi ateş azabından koru", "source": "Âl-i İmrân, 3/16"}, "en": {"content": "Our Lord! Indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire.", "source": "Surah Ali ''Imran, 3:16"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Yaşamak benim için hayırlı olduğu sürece beni yaşat. Ölmek benim için hayırlı olduğunda da benim canımı al!", "source": "Buhârî, Merdâ, 19"}, "en": {"content": "O Allah! Keep me alive as long as life is good for me, and cause me to die when death is better for me.", "source": "Sahih al-Bukhari, Book of Patients, 19"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Senden hayırlı olan işleri yapmayı, aklın ve dinin çirkin gördüğü şeyleri terk etmeyi ve fakirlerin sevgisini istiyorum.", "source": "Context: Mâlik, Duâ, No: 508"}, "en": {"content": "O Allah! I ask You for the ability to do good deeds, to abandon evil deeds, and to love the poor.", "source": "Muwatta Malik, Book of Dua, No: 508"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Senden düzgün bir yaşantı, temiz bir ölüm ve rezil rüsva olmadan sana dönebilmeyi istiyorum.", "source": "İbn Ebu Şeybe, Duâ, 1, No: 29134"}, "en": {"content": "O Allah! I ask You for a righteous life, a clean death, and a return to You that is not disgraceful or humiliating.", "source": "Musannaf Ibn Abi Shaybah, Book of Dua, No: 29134"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Lütfundan bize rızık ver, bizi rızkından mahrum etme, bize verdiğin rızıkları bizim için bereketli yap, katında bulunan nimetlere rağbetimizi arttır ve bizi gönül zengini eyle.", "source": "İbn Ebu Şeybe, Duâ, 42"}, "en": {"content": "O Allah! Grant us provision from Your bounty, do not deprive us of Your provision, bless for us what You provide, increase our desire for what is with You, and make us self-sufficient.", "source": "Musannaf Ibn Abi Shaybah, Book of Dua, 42"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbim! Onlar (anne ve babam) nasıl küçüklükte beni şefkatle eğitip yetiştirdilerse şimdi sen de onlara merhamet göster.", "source": "İsrâ, 17/24"}, "en": {"content": "My Lord! Have mercy upon them as they brought me up when I was small.", "source": "Surah Al-Isra, 17:24"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Gazabından rızana, cezandan affına sığınırım. Senden sana sığınırım. sana tüm övgüleri saysam yine de bitiremem. Sen kendini nasıl övdüysen öylesin.", "source": "Müslim, Salât, 222"}, "en": {"content": "O Allah! I seek refuge in Your pleasure from Your wrath, and in Your forgiveness from Your punishment. I seek refuge in You from You. I cannot enumerate Your praise; You are as You have praised Yourself.", "source": "Sahih Muslim, Book of Salat, 222"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Rahmetinin gereklerini, mağfiretinin sürekliliğini, her türlü günahtan uzak ve salim olmayı, her türlü iyilik ve nimetleri, cennete girerek felaha ermeyi, yardımınla cehennem ateşinden kurtulmayı istiyorum.", "source": "Hâkim, Deavât, No: 1925"}, "en": {"content": "O Allah! I ask You for the causes of Your mercy, the actions that draw Your forgiveness, safety from every sin, the gain of every righteousness, entry into Paradise, and salvation from the Fire.", "source": "Al-Hakim, Al-Da''awat, No: 1925"}}',true),
('prayer','hope','any','{"tr": {"content": "Rabbimiz! Nurumuzu arttır, eksiltme ve bizi bağışla. Şüphesiz senin her şeye gücün yeter.", "source": "Tahrîm, 66/8"}, "en": {"content": "Our Lord! Perfect for us our light and forgive us. Indeed, You are over all things competent.", "source": "Surah Al-Tahrim, 66:8"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Helal olan nimetlerinle yetinmemi, haramlardan müstağni olmamı ihsan eyle, fazlı kereminle beni senden başkasına muhtaç eyleme.", "source": "Hâkim, Deavât, No: 1973"}, "en": {"content": "O Allah! Make me content with what is lawful and keep me away from what is prohibited, and by Your grace make me independent of all besides You.", "source": "Al-Hakim, Al-Da''awat, No: 1973"}}',true),
('prayer','hope','any','{"tr": {"content": "Allah’ım! Kederden, üzüntüden, tembellikten, cimrilikten, korkaklıktan, borç yükünden ve halkın galeyana gelerek taşkınlığından sana sığınırım.", "source": "Nesâî, İstiâze, 25"}, "en": {"content": "O Allah! I seek refuge in You from anxiety, sorrow, weakness, laziness, miserliness, cowardice, the burden of debt, and from being overpowered by men.", "source": "Sunan an-Nasa''i, Book of Isti''adha, 25"}}',true),
('prayer','dhikr','any','{"tr": {"content": "Allah’ım! Seni zikretmek, sana şükretmek ve sana güzelce ibadet etmek için bana yardım et.", "source": "Ebû Dâvûd, Tefrîu Ebvâbi’l-Vitr, 26"}, "en": {"content": "O Allah! Help me to remember You, to thank You, and to worship You in the best manner.", "source": "Sunan Abi Dawud, Book of Witras, 26"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ey Rabbimiz! Biz kendimize zulmettik. Eğer bizi bağışlamaz, bize acımazsan mutlaka ziyan edenlerden oluruz!", "source": "A’râf, 7/23"}, "en": {"content": "Our Lord! We have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers.", "source": "Surah Al-A''ref, 7:23"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Nimetlerinin yok olmasından, sağlığımın bozulmasından, ansızın gelecek cezandan ve öfkene sebep olan her şeyden sana sığınırım.", "source": "Müslim, Rikâk, 96"}, "en": {"content": "O Allah! I seek refuge in You from the decline of Your blessings, the change of Your protection, the suddenness of Your punishment, and all of Your anger.", "source": "Sahih Muslim, Book of Ar-Riqaq, 96"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Faydasız ilimden, huşu duymayan kalpten, doymayan nefisten ve kabul edilmeyen duadan sana sığınırım.", "source": "Nesâî, İstiâze, 64"}, "en": {"content": "O Allah! I seek refuge in You from knowledge that does not benefit, from a heart that does not fear You, from a soul that is not satisfied, and from a prayer that is not answered.", "source": "Sunan an-Nasa''i, Book of Isti''adha, 64"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Kullarını mahşerde topladığın veya mahşerde kaldırdığın gün beni azabından koru.", "source": "Tirmizî, Deavât, 18"}, "en": {"content": "O Allah! Protect me from Your punishment on the Day You resurrect Your servants.", "source": "Jami` at-Tirmidhi, Book of Supplications, 18"}}',true),
('prayer','prayer','any','{"tr": {"content": "Bizi yedirip içiren ve bizi Müslümanlardan eyleyen Allah’a hamdolsun.", "source": "Tirmizî, Deavât, 56"}, "en": {"content": "Praise be to Allah who fed us and gave us drink and made us Muslims.", "source": "Jami` at-Tirmidhi, Book of Supplications, 56"}}',true),
('prayer','prayer','any','{"tr": {"content": "(Rabbim!) Arkadan gelecekler içinde iyilikle anılmayı bana nasip eyle!", "source": "Şu’arâ, 26/84"}, "en": {"content": "My Lord! Grant me an honorable mention among later generations.", "source": "Surah Al-Shu''ara, 26:84"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım! Bana öğrettiğin ilim ile beni faydalandır, bana fayda verecek ilmi bana öğret ve benim ilmimi arttır. Her hâl üzere Allah’a hamdolsun. Cehennem ehlinin hâlinden Allah’a sığınırım.", "source": "Tirmizî, Deavât, 130"}, "en": {"content": "O Allah! Benefit me with the knowledge You have taught me, teach me what will benefit me, and increase my knowledge. Praise be to Allah in all circumstances. I seek refuge in Allah from the state of the people of Hell.", "source": "Jami` at-Tirmidhi, Book of Supplications, 130"}}',true),
('prayer','purpose','any','{"tr": {"content": "Allah’ım! Benim yaratılışımı güzel kıldığın gibi ahlakımı da güzelleştir...", "source": "İbn Hanbel, I, 403"}, "en": {"content": "O Allah! As You have made my physical creation beautiful, make my character beautiful.", "source": "Musnad Ahmad, I, 403"}}',true),
('prayer','dhikr','any','{"tr": {"content": "Allah’ım seni zikretmek, sana şükretmek, sana güzelce ibadet etmekte bize yardım et.", "source": "İbn Hanbel, II, 299"}, "en": {"content": "O Allah! Help us to remember You, to thank You, and to worship You beautifully.", "source": "Musnad Ahmad, II, 299"}}',true),
('prayer','prayer','any','{"tr": {"content": "(Rabbim) Beni, naim cennetine girenlerden eyle!", "source": "Şu’arâ, 26/85"}, "en": {"content": "My Lord! Admit me to the Garden of Pleasure.", "source": "Surah Al-Shu''ara, 26:85"}}',true),
('prayer','dhikr','any','{"tr": {"content": "Rabbim! Bana ve anne-babama lütfettiğin nimete şükretmeye, razı olacağın işleri yapmaya beni muvaffak kıl. Benden gelecek nesli hayırlı eyle, pişmanlıkla dönüp senin kapına başvurmaktayım ve ben süphesiz sana boyun eğenlerdenim.", "source": "Ahkâf, 46/15"}, "en": {"content": "My Lord! Enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to do righteousness of which You approve. And make righteous for me my offspring. Indeed, I have repented to You, and indeed, I am of the Muslims.", "source": "Surah Al-Ahqaf, 46:15"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Kalbimde nur, gözümde nur, kulağımda nur, sağımda nur, solumda nur, üstümde nur, altımda nur, önümde nur var eyle, benim nurumu artır.", "source": "Müslim, Müsâfirîn, 181"}, "en": {"content": "O Allah! Place light in my heart, light in my sight, light in my hearing, light on my right, light on my left, light above me, light below me, light in front of me, and increase my light.", "source": "Sahih Muslim, Book of Travellers, 181"}}',true),
('prayer','prayer','any','{"tr": {"content": "Ödül ve ceza gününün tek hâkimi. (Rabbimiz!) Ancak sana kulluk eder ve yalnız senden yardım dileriz.", "source": "Fâtiha, 1/4-5"}, "en": {"content": "Sovereign of the Day of Recompense. It is You we worship and You we ask for help.", "source": "Surah Al-Fatihah, 1:4-5"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Hesap kurulacağı gün beni, anamı, babamı ve müminleri bağışla!", "source": "İbrahim, 14/41"}, "en": {"content": "Our Lord! Forgive me and my parents and the believers on the Day the account is established.", "source": "Surah Ibrahim, 14:41"}}',true),
('prayer','prayer','any','{"tr": {"content": "Rabbimiz! Şüphesiz ki sen gizlediğimizi de açıkladığımızı da bilirsin. Yerde ve gökte hiçbir şey Allah’a gizli kalmaz.", "source": "İbrahim, 14/38"}, "en": {"content": "Our Lord! Indeed You know what we conceal and what we declare, and nothing is hidden from Allah on the earth or in the heaven.", "source": "Surah Ibrahim, 14:38"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! (Haktan) ayrılmaktan, iki yüzlülükten ve kötü ahlaktan sana sığınırım.", "source": "Ebû Dâvûd, Vitr, 32"}, "en": {"content": "O Allah! I seek refuge in You from division, hypocrisy, and bad character.", "source": "Sunan Abi Dawud, Book of Witras, 32"}}',true),
('prayer','prayer','any','{"tr": {"content": "Allah’ım! Sen affedicisin, Kerim’sin, affı seversin, beni affet", "source": "Tirmizî, Deavât, 84"}, "en": {"content": "O Allah! You are forgiving, noble, and You love forgiveness, so forgive me.", "source": "Jami` at-Tirmidhi, Book of Supplications, 84"}}',true);
